// Spike 6: layered package split — "opc" + "xml" are format-agnostic,
// format packages sit on top.
// Proof in two acts:
//  A) the pptx invert flow (spike 3) still passes on the restructured layers,
//     now with spec-correct slide ordering via p:sldIdLst;
//  B) a ~40-line WordprocessingML layer on the SAME opc+xml packages reads
//     and edits a .docx generated by python-docx (validated by 06-validate.py).
import { readFile, writeFile } from "node:fs/promises";
import { Presentation } from "./packages/pptx/index.mjs";
import { OpcPackage } from "./packages/opc/index.mjs";
import { parseXml, serializeXml, walk, firstChild, childrenOf, el, text } from "./packages/xml/index.mjs";

// --- Act A: pptx on the layered packages -----------------------------------
{
  const bytes = new Uint8Array(await readFile("../tests/fixtures/hagar-presentatie.pptx"));
  const pres = Presentation.open(bytes);
  console.log(`pptx: ${pres.slides.length} slides via p:sldIdLst -> ${pres.slides.map((s) => s.partName.match(/slide(\d+)/)[1]).join(",")}`);
  for (const slide of pres.slides) {
    slide.setBackground("1A1A2E");
    for (const shape of slide.shapes()) {
      if (shape.hasTextFrame) for (const run of shape.runs()) run.setFontColor("E8E8F0");
      if (shape.isPicture && !shape.imageBlob()) throw new Error("blob resolve failed");
    }
  }
  await writeFile("out/spike6-inverted.pptx", pres.save());
  console.log("pptx: wrote out/spike6-inverted.pptx (validate with 03-validate.py)");
}

// --- Act B: a minimal WordprocessingML layer on the same foundation --------
// This is the entire format-specific code needed to read paragraphs and
// recolor runs in a .docx — everything else is the shared opc+xml layers.
class WordDocument {
  #pkg; #partName; #tree;
  static open(bytes) { return new WordDocument(OpcPackage.open(bytes)); }
  constructor(pkg) {
    this.#pkg = pkg;
    this.#partName = pkg.mainPart(); // same officeDocument rel as pptx!
    this.#tree = parseXml(pkg.read(this.#partName));
  }
  *paragraphs() {
    for (const p of walk(this.#tree, "w:p")) {
      yield {
        text: [...walk(childrenOf(p), "w:t")].map(text).join(""),
        setColor: (hex) => {
          for (const r of walk(childrenOf(p), "w:r")) {
            let rPr = firstChild(r, "w:rPr");
            if (!rPr) {
              rPr = el("w:rPr");
              childrenOf(r).unshift(rPr);
            }
            const kids = childrenOf(rPr);
            const idx = kids.findIndex((c) => firstChild(rPr, "w:color") === c);
            const color = el("w:color", { "w:val": hex });
            if (idx >= 0) kids.splice(idx, 1, color);
            else kids.push(color);
          }
        },
      };
    }
  }
  save() {
    this.#pkg.write(this.#partName, serializeXml(this.#tree));
    return this.#pkg.save();
  }
}

{
  const bytes = new Uint8Array(await readFile("out/spike6-input.docx"));
  const doc = WordDocument.open(bytes);
  const texts = [];
  for (const para of doc.paragraphs()) {
    if (para.text) texts.push(para.text);
    para.setColor("C0392B");
  }
  console.log(`docx: read ${texts.length} paragraphs: ${JSON.stringify(texts)}`);
  await writeFile("out/spike6-recolored.docx", doc.save());
  console.log("docx: wrote out/spike6-recolored.docx (validate with 06-validate.py)");
}
